{
  "status": "SUPPORTED",
  "task_summary": "Search storage for fastening tools and components, fasten the workpiece at the marked location, and place the tool on the workbench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "storage_structure",
        "entity_kind": "OBJECT",
        "function": "Enclosed space holding tools or parts",
        "required_count": 3,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["cabinet", "drawer"],
        "required_properties": ["closed", "has_contents"]
      },
      {
        "id": "workpiece",
        "entity_kind": "OBJECT",
        "function": "Item to be fastened",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["block", "assembly_part"],
        "required_properties": ["physical_object"]
      },
      {
        "id": "fastening_tool",
        "entity_kind": "OBJECT",
        "function": "Implement used to secure parts",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "hammer"],
        "required_properties": ["tool_for_fastening"]
      },
      {
        "id": "compatible_component",
        "entity_kind": "OBJECT",
        "function": "Part to be attached",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["screw", "bolt", "nut", "plate"],
        "required_properties": ["attachment_part"]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "Support surface for the task",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "desk", "bench"],
        "required_properties": ["support_surface", "flat_area"]
      }
    ],
    "functional_relations": [
      {
        "id": "contains_tool",
        "relation": "CONTAINS",
