      ,
        "required": true
      },
      {
        "id": "contains_component",
        "relation": "CONTAINS",
        "participant_roles": ["storage_structure", "compatible_component"]
      ,
        "required": true
      },
      {
        "id": "located_at",
        "relation": "LOCATED_AT",
        "participant_roles": ["workpiece", "workbench"]
      ,
        "required": true
      },
      {
        "id": "used_on",
        "relation": "USED_ON",
        "participant_roles": ["fastening_tool", "workpiece"]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "inspect_storage",
        "operation": "INSPECT",
        "participant_roles": ["storage_structure", "fastening_tool", "compatible_component"],
        "operation_count": 3
      },
      {
        "id": "retrieve_tool",
        "operation": "RETRIEVE",
        "participant_roles": ["fastening_tool", "storage_structure"],
        "operation_count": 1
      },
      {
        "id": "retrieve_component",
        "operation": "RETRIEVE",
        "participant_roles": ["compatible_component", "storage_structure"],
        "operation_count": 1
      },
      {
        "id": "perform_fastening",
        "operation": "FASTEN",
        "participant_roles": ["fastening_tool", "compatible_component", "workpiece"],
        "operation_count": 1
      },
      {
        "id": "place_tool",
        "operation": "PLACE",
        "participant_roles": ["fastening_tool", "workbench"],
        "operation_count": 1
      }
    ]
  },
